# Saját rajzolású, egyszerű SVG ikonok a szójátékokhoz (100x100). Nem a könyv képei.
def svg(inner): return '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100">'+inner+'</svg>'
SK='#FDE7C9'; 
def person(hair='#6B4423', gender='m', age='adult', beard=False, glasses=False, mustache=False, long_hair=False, shirt='#4F8FD6', size=1.0, grey=False):
    hc='#BDBDBD' if grey else hair
    s=size; hh=44 if age!='child' else 52
    body=f'<path d="M22 100 q0 -30 28 -30 q28 0 28 30z" fill="{shirt}"/>'
    if age=='child': body=f'<path d="M30 100 q0 -24 20 -24 q20 0 20 24z" fill="{shirt}"/>'
    hairb=''
    if long_hair: hairb=f'<path d="M27 48 q-4 -34 23 -34 q27 0 23 34 l2 24 q-8 6 -12 -4 l-2 -20 h-22 l-2 20 q-4 10 -12 4z" fill="{hc}"/>'
    elif gender=='m' or age!='child': hairb=f'<path d="M30 44 q-3 -28 20 -28 q23 0 20 28 q-6 -12 -20 -12 q-14 0 -20 12z" fill="{hc}"/>'
    head=f'<circle cx="50" cy="{hh}" r="{20 if age!="child" else 17}" fill="{SK}"/>'
    face=f'<circle cx="43" cy="{hh}" r="2.4" fill="#333"/><circle cx="57" cy="{hh}" r="2.4" fill="#333"/><path d="M44 {hh+9} q6 5 12 0" stroke="#A04B3A" stroke-width="2" fill="none" stroke-linecap="round"/>'
    extra=''
    if beard: extra+=f'<path d="M33 {hh+4} q0 22 17 22 q17 0 17 -22 q-6 10 -17 10 q-11 0 -17 -10z" fill="{hc}"/>'
    if mustache: extra+=f'<path d="M41 {hh+6} q9 -5 18 0 q-9 4 -18 0z" fill="{hc}"/>'
    if glasses: extra+=f'<circle cx="43" cy="{hh}" r="7" fill="none" stroke="#333" stroke-width="2"/><circle cx="57" cy="{hh}" r="7" fill="none" stroke="#333" stroke-width="2"/><path d="M50 {hh} h0" stroke="#333" stroke-width="2"/>'
    if long_hair: return svg(f'<g>{hairb}{body}{head}{face}{extra}<path d="M30 40 q20 -22 40 0 q-20 -8 -40 0z" fill="{hc}"/></g>')
    return svg(body+head+hairb+face+extra)
def circle(c): return svg(f'<circle cx="50" cy="50" r="38" fill="{c}" stroke="#555" stroke-width="3"/>')
